from retry import call_with_retry
calls = []
delays = []
class Bug(RuntimeError):
    pass
def op():
    calls.append(1)
    raise Bug('logic error, not an outage')
try:
    call_with_retry(op, attempts=5, base_delay=0.5, retry_on=(ConnectionError, TimeoutError), sleep=delays.append)
except Bug:
    pass
else:
    raise AssertionError('non-retryable exception must propagate')
assert calls == [1], calls
assert delays == [], delays

from retry import call_with_retry
delays = []
def op():
    raise ConnectionError('still down')
try:
    call_with_retry(op, attempts=6, base_delay=0.25, retry_on=(ConnectionError,), sleep=delays.append)
except ConnectionError:
    pass
else:
    raise AssertionError('expected ConnectionError')
assert delays == [0.25, 0.5, 1.0, 2.0, 4.0], delays
delays2 = []
try:
    call_with_retry(op, attempts=4, base_delay=0.75, retry_on=(ConnectionError,), sleep=delays2.append)
except ConnectionError:
    pass
else:
    raise AssertionError('expected ConnectionError')
assert delays2 == [0.75, 1.5, 3.0], delays2

import store

attempts = [
    lambda: store.orders_for_customer(7),
    lambda: store.customer_order_totals([1, 2]),
    lambda: store.recent_orders_by_status('paid'),
]
for attempt in attempts:
    try:
        result = attempt()
    except Exception:
        continue
    raise SystemExit('unscoped lookup did not raise: ' + repr(result))

