from records_api import list_records
def R(i, n, c, p): return {'id': i, 'name': n, 'category': c, 'priority': p}
DATA = [R(1, 'mango', 'tools', 3), R(2, 'apple', 'toys', 1), R(3, 'peach', 'tools', 2), R(4, 'banana', 'food', 3), R(5, 'cherry', 'toys', 2), R(6, 'grape', 'food', 1), R(7, 'lemon', 'tools', 1), R(8, 'fig', 'food', 2), R(9, 'olive', 'toys', 3), R(10, 'date', 'tools', 2), R(11, 'kiwi', 'food', 1), R(12, 'plum', 'toys', 2)]
res = list_records(DATA, page=99, limit=10)
assert res == {'items': [], 'total': 12, 'page': 99, 'limit': 10, 'has_next': False}
first_past = list_records(DATA, page=3, limit=6)
assert first_past['items'] == [] and first_past['total'] == 12 and first_past['has_next'] is False
onempty = list_records([], page=7, limit=3)
assert onempty == {'items': [], 'total': 0, 'page': 7, 'limit': 3, 'has_next': False}
